import SlsWebLogger from "js-sls-logger-v3";
import * as browser from "webextension-polyfill";
import * as chrome from "webextension-polyfill";
import {guid} from "./url-tool";

//阿里日志配置
const ali_log_opts = {
    host: process.env.VUE_APP_ALILOG_HOST,
    project: process.env.VUE_APP_ALILOG_PROJECT,
    logstore: process.env.VUE_APP_ALILOG_LOGSTORE,
    time: 2,
    count: 1,
}

const logger = { send() {} }                 

const EDGE_PATTERN = /edge\/([\d.]+)|edg\/([\d.]+)/
const IE_PATTERN1 = /rv:([\d.]+)\) like gecko/
const IE_PATTERN2 = /msie ([\d.]+)/
const FIREFOX_PATTERN = /firefox\/([\d.]+)/
const CHROME_PATTERN = /chrome\/([\d.]+)/
const OPERA_PATTERN = /opera.([\d.]+)/
const SAFARI_PATTERN = /version\/([\d.]+).*safari/

export function getBrowserType() {
    let type = "other";
    let ua = navigator.userAgent.toLowerCase()
    if (EDGE_PATTERN.test(ua)) {
        type = 'Edge';
    }else if (IE_PATTERN1.test(ua)) {
        type = 'IE';
    }else if (IE_PATTERN2.test(ua)) {
        type = 'IE';
    }else if (FIREFOX_PATTERN.test(ua)) {
        type = 'Firefox';
    }else if (CHROME_PATTERN.test(ua)) {
        type = 'Chrome';
    }else if (OPERA_PATTERN.test(ua)) {
        type = 'Opera';
    }else if (SAFARI_PATTERN.test(ua)) {
        type = 'Safari';
    }
    return type;
}

export async function getUUID(){
    let data = await browser.storage.local.get(["uuid"]);
    if(data.uuid == undefined){
        let uuid = guid();
        await browser.storage.local.set({'uuid': uuid});
        return uuid;
    }else{
        return data.uuid;
    }
}

export async function getClientVersion(){
    let options = browser.runtime.getManifest();
    return options.version;
}

export async function setInstallTime(){
    let data = await browser.storage.local.get(["install_time"]);
    if(data.install_time == undefined){
        let install_time = Math.floor(Date.now()/1000);
        await browser.storage.local.set({'install_time': install_time});
    }
}

export async function getInstallTime(){
    let data = await browser.storage.local.get(["install_time"]);
    if(data.install_time == undefined){
        return 0;
    }else{
        return data.install_time;
    }
}

export async function getUserProfileId(){
    const data = await chrome.storage.local.get(['userProfileId']);
    return data?.userProfileId || "";
}

export async function sendAliLog(...argv){
    await chrome.runtime.sendMessage({
        'code': 'alilog_send',
        'event_type': argv[0],
        'event_data':argv[1]
    });
}

export function getCurrentHtmlContent(){
    return document.getElementsByTagName('html')[0].outerHTML;
}

/*记录阿里云日志
* 参数方式：event_type, event_data
*/
export async function aliLog(event_type,event_data={}){
    let uuid = await getUUID()
    let install_time = await getInstallTime()
    let client_version = await getClientVersion()
    
    const user_profile_id = await getUserProfileId();

    let storageData = await browser.storage.local.get(['platform', 'browserType', 'language', 'userAgent']);

    let log_data = {
        event_source:'2j',
        event_type: event_type,
        install_time: install_time,//取缓存数据
        event_time: Math.floor(Date.now()/1000),//取当前时间
        log_version: 'v1',//日志版本
        uuid: uuid,
        user_profile_id: user_profile_id || "",
        version: client_version,
        platform: storageData.platform ? storageData.platform : '',
        browser_type: storageData.browserType ? storageData.browserType : '',
        language: storageData.language ? storageData.language : '',
        user_agent: storageData.userAgent ? storageData.userAgent : ''
    }

    Object.assign(log_data,event_data);

    const str_log_data = {};
    for (const key in log_data) {
        if (Object.hasOwnProperty.call(log_data, key)) {
            const value = log_data[key];
            if(!["string","number"].includes(typeof value)){
                str_log_data[key] = JSON.stringify(value);
            }else{
                str_log_data[key] = value;
            }
        }
    }

    logger.send(str_log_data)
}


/**
 * 开始安装时，记录通用常数
 */
export async function setGeneralParamsOnInstall(){
    setInstallTime();

    const browserType = getBrowserType();
    await chrome.storage.local.set({'browserType': browserType});
    await chrome.storage.local.set({'platform': navigator.platform});
    await chrome.storage.local.set({'language': navigator.language});
    await chrome.storage.local.set({'userAgent': navigator.userAgent});
}